document.querySelectorAll('[data-connector-search]').forEach(input=>{const section=input.closest('.connector-directory');const cards=[...section.querySelectorAll('.connector-grid>li')];const output=section.querySelector('[data-connector-count]');input.addEventListener('input',()=>{const query=input.value.trim().toLocaleLowerCase();let count=0;cards.forEach(card=>{const visible=card.textContent.toLocaleLowerCase().includes(query);card.hidden=!visible;if(visible)count++});output.textContent=count+' / '+cards.length})});
